            if color != 0 and all(grid[i][j] == color
                                  for i in range(r, r + 3)
                                  for j in range(c, c + 3)):
                centers[(r + 1, c + 1)] = color

    lines = {}
    conflicts = set()
    for (r, c), color in centers.items():
        for j in range(w):
            pos = (r, j)
            if pos in lines and lines[pos] != color:
                conflicts.add(pos)
            else:
                lines[pos] = color
        for i in range(h):
            pos = (i, c)
            if pos in lines and lines[pos] != color:
                conflicts.add(pos)
            else:
                lines[pos] = color

    out = [row[:] for row in grid]
    for (r, c), color in lines.items():
        out[r][c] = 0 if (r, c) in conflicts else color
    for r, c in conflicts:
        out[r][c] = 0
    return out
